import { and, count, desc, eq, gte, inArray, lt, lte } from "drizzle-orm";
import { newId } from "@/lib/id";
import { activityEvents, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toActivityEvent } from "./_mappers";
import type { ActivityFilterInput } from "@/schemas/activity";
import type { ActivityEvent, ActivitySubjectKind } from "@/types/activity";
import type { IsoTimestamp, OrgId, Page } from "@/types/common";

export async function insertActivity(
  event: Omit<ActivityEvent, "id">,
): Promise<ActivityEvent> {
  const row = getDb()
    .insert(activityEvents)
    .values({
      id: newId(),
      orgId: event.orgId,
      action: event.action,
      actorId: event.actorId,
      subjectKind: event.subjectKind,
      subjectId: event.subjectId,
      projectId: event.projectId,
      summary: event.summary,
      metadata: JSON.stringify(event.metadata),
      occurredAt: event.occurredAt,
    })
    .returning()
    .get();

  return toActivityEvent(row);
}

export async function listActivity(
  input: ActivityFilterInput,
): Promise<Page<ActivityEvent>> {
  const db = getDb();
  const sort = {
    sortColumn: activityEvents.occurredAt,
    idColumn: activityEvents.id,
  };

  const filters = compact(
    orgPredicate(activityEvents.orgId, input.orgId),
    input.action === undefined || input.action.length === 0
      ? undefined
      : inArray(activityEvents.action, [...input.action]),
    input.actorId === undefined
      ? undefined
      : eq(activityEvents.actorId, input.actorId),
    input.projectId === undefined
      ? undefined
      : eq(activityEvents.projectId, input.projectId),
    input.subjectKind === undefined
      ? undefined
      : eq(activityEvents.subjectKind, input.subjectKind),
    input.since === undefined
      ? undefined
      : gte(activityEvents.occurredAt, input.since),
    input.until === undefined
      ? undefined
      : lte(activityEvents.occurredAt, input.until),
  );

  const total = db
    .select({ value: count() })
    .from(activityEvents)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(activityEvents)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(activityEvents.occurredAt), desc(activityEvents.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    toActivityEvent,
    (row) => ({ id: row.id, sortValue: row.occurredAt }),
  );
}

/** The "history" tab of one issue, project or member. */
export async function listActivityForSubject(
  orgId: OrgId,
  subjectKind: ActivitySubjectKind,
  subjectId: string,
): Promise<readonly ActivityEvent[]> {
  const rows = getDb()
    .select()
    .from(activityEvents)
    .where(
      and(
        orgPredicate(activityEvents.orgId, orgId),
        eq(activityEvents.subjectKind, subjectKind),
        eq(activityEvents.subjectId, subjectId),
      ),
    )
    .orderBy(desc(activityEvents.occurredAt))
    .all();

  return rows.map(toActivityEvent);
}

/**
 * The only sanctioned deletion path: the retention sweep. `before` comes from
 * the plan's `retentionDays`, never from a user-supplied date.
 */
export async function purgeActivityBefore(
  orgId: OrgId,
  before: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .delete(activityEvents)
    .where(
      and(
        orgPredicate(activityEvents.orgId, orgId),
        lt(activityEvents.occurredAt, before),
      ),
    )
    .returning({ id: activityEvents.id })
    .all();

  return rows.length;
}
import type {
  EventHandler,
  TaskflowEventMap,
  TaskflowEventPayload,
  TaskflowEventType,
  Unsubscribe,
} from "@/types/event";

/**
 * In-process, typed publish/subscribe bus.
 *
 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
 * every reactive concern `subscribe()`s at module init (see
 * `src/server/services/event-registry.ts`). Handlers are isolated — one
 * throwing handler never fails the emit or the sibling handlers.
 */

type HandlerSet = Set<EventHandler<TaskflowEventType>>;

const handlers = new Map<TaskflowEventType, HandlerSet>();

const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();

/** Registers a handler for one event type. Call the return value to detach. */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set = handlers.get(type) ?? new Set();
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

/** Registers a handler that detaches itself after the first delivery. */
export function subscribeOnce<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const off = subscribe(type, (payload) => {
    off();
    return handler(payload);
  });
  return off;
}

/**
 * Publishes an event to every subscriber. Resolves once all handlers settle;
 * rejected handlers are reported to the error sinks, never rethrown.
 */
export async function emit<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): Promise<void> {
  const set = handlers.get(type);
  if (!set || set.size === 0) return;

  const results = await Promise.allSettled(
    [...set].map(async (handler) => {
      await (handler as EventHandler<K>)(payload);
    }),
  );

  for (const result of results) {
    if (result.status === "rejected") {
      reportHandlerError(type, result.reason);
    }
  }
}

/** Fire-and-forget variant for call sites that must not await delivery. */
export function emitAndForget<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): void {
  void emit(type, payload).catch((error: unknown) => {
    reportHandlerError(type, error);
  });
}

export function onHandlerError(
  sink: (type: TaskflowEventType, error: unknown) => void,
): Unsubscribe {
  errorSinks.add(sink);
  return () => {
    errorSinks.delete(sink);
  };
}

function reportHandlerError(type: TaskflowEventType, error: unknown): void {
  for (const sink of errorSinks) {
    try {
      sink(type, error);
    } catch {
      // A failing error sink must never escalate.
    }
  }
}

/** Number of live subscribers for an event; used by tests and diagnostics. */
export function subscriberCount(type: TaskflowEventType): number {
  return handlers.get(type)?.size ?? 0;
}

/** Detaches every handler. Test-only — never call from application code. */
export function resetEventBus(): void {
  handlers.clear();
  errorSinks.clear();
}

