208	/** Groups a feed page by calendar day, newest day first. */
209	export function groupByDay(
210	  events: readonly ActivityEvent[],
211	): readonly ActivityGroup[] {
212	  const byDay = new Map<string, ActivityEvent[]>();
213	
214	  for (const event of events) {
215	    const day = event.occurredAt.slice(0, 10);
216	    const bucket = byDay.get(day) ?? [];
217	    bucket.push(event);
218	    byDay.set(day, bucket);
219	  }
220	
221	  return [...byDay.entries()]
222	    .sort(([a], [b]) => (a < b ? 1 : -1))
223	    .map(([day, dayEvents]) => ({ day, events: dayEvents }));
224	}
