566	function snippetAround(content: string, query: string): string {
567	  const at = content.toLowerCase().indexOf(query.toLowerCase());
568	  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);
569	
570	  const start = Math.max(0, at - SNIPPET_RADIUS);
571	  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
572	  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
573	    end < content.length ? "…" : ""
574	  }`;
575	}
