609	export async function recomputeUsage(
610	  orgId: OrgId,
611	): Promise<OrganizationUsage> {
612	  const usage = await usageRepo.recomputeUsage(orgId);
613	  const org = await orgRepo.findOrgById(orgId);
614	  if (!org) return usage;
615	
616	  const limits = getPlanLimits(org.plan);
617	
618	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
619	    await emit("billing.limit_exceeded", {
620	      orgId,
621	      actorId: null,
622	      occurredAt: toIsoTimestamp(new Date()),
623	      resource: "seats",
624	      limit: limits.seats,
625	      used: usage.seatsUsed,
626	    });
627	  }
628	
629	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
630	    await emit("billing.limit_exceeded", {
631	      orgId,
632	      actorId: null,
633	      occurredAt: toIsoTimestamp(new Date()),
634	      resource: "projects",
635	      limit: limits.projects,
636	      used: usage.projectsUsed,
637	    });
638	  }
639	
640	  return usage;
641	}
