676	/**
677	 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
678	 *
679	 * Must call (do not reimplement): getPlanLimits, isArchived
680	 */
681	import { getPlanLimits } from "@/config/plan-limits";
682	import { createLogger } from "@/lib/logger";
683	import { isArchived } from "@/lib/soft-delete";
684	import * as activityRepo from "@/server/repositories/activity-repository";
685	import * as issueRepo from "@/server/repositories/issue-repository";
686	import * as orgRepo from "@/server/repositories/organization-repository";
687	import * as searchRepo from "@/server/repositories/search-repository";
688	import * as usageRepo from "@/server/repositories/usage-repository";
689	import { toIsoTimestamp } from "@/types/common";
690	import { runJob } from "./types";
691	import type { JobResult } from "@/server/jobs/types";
692	
693	const ORG_BATCH = 25;
694	const PAGE_SIZE = 100;
695	const MS_PER_DAY = 24 * 60 * 60 * 1000;
696	
697	const logger = createLogger("cleanup-archived-job");
698	
699	/**
700	 * The retention sweep. Soft-deleted rows are kept for as long as the plan
701	 * promises and no longer: the cut-off comes from `retentionDays`, so an
702	 * enterprise tenant keeps years of history where a free one keeps a month.
703	 *
704	 * Only the search documents are actually dropped here — the issue rows stay,
705	 * because the audit log still points at them — while the audit rows past the
706	 * window are purged outright.
707	 */
708	export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
709	  return runJob("cleanup-archived", async (result) => {
710	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
711	
712	    for (const orgId of orgIds) {
713	      const org = await orgRepo.findOrgById(orgId);
714	      if (!org) continue;
715	
716	      const { retentionDays } = getPlanLimits(org.plan);
717	      const cutoff = toIsoTimestamp(
718	        new Date(now.getTime() - retentionDays * MS_PER_DAY),
719	      );
720	
721	      const archived = await issueRepo.listIssues({
722	        orgId,
723	        limit: PAGE_SIZE,
724	        cursor: null,
725	        includeArchived: true,
726	      });
727	
728	      for (const issue of archived.items) {
729	        if (!isArchived(issue)) continue;
730	        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;
731	
732	        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
733	        result.processed += 1;
734	      }
735	
736	      try {
737	        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
738	        result.processed += purged;
739	      } catch (error) {
740	        result.failed += 1;
741	        logger.error("activity purge failed", {
742	          orgId,
743	          reason: error instanceof Error ? error.message : String(error),
744	        });
745	      }
746	    }
747	  });
748	}
