791	/**
792	 * Groups a flat event list into the day buckets `ActivityFeed` consumes,
793	 * newest day first and newest event first within a day.
794	 */
795	export function groupEventsByDay(
796	  events: readonly ActivityEvent[],
797	): readonly ActivityGroup[] {
798	  const byDay = new Map<string, ActivityEvent[]>();
799	
800	  for (const event of events) {
801	    const day = activityDay(event);
802	    const bucket = byDay.get(day) ?? [];
803	    bucket.push(event);
804	    byDay.set(day, bucket);
805	  }
806	
807	  return [...byDay.entries()]
808	    .sort(([a], [b]) => b.localeCompare(a))
809	    .map(([day, bucket]) => ({
810	      day,
811	      events: [...bucket].sort((a, b) =>
812	        b.occurredAt.localeCompare(a.occurredAt),
813	      ),
814	    }));
