1144	/**
1145	 * Brings `databasePath` up to date. Generated migrations win when they exist;
1146	 * otherwise the embedded schema is pushed. Safe to run repeatedly — every
1147	 * statement is `IF NOT EXISTS`.
1148	 */
1149	export async function runMigrations(
1150	  databasePath: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH,
1151	): Promise<void> {
1152	  const absolute = resolve(process.cwd(), databasePath);
1153	  mkdirSync(dirname(absolute), { recursive: true });
1154	
1155	  const sqlite = new Database(absolute);
1156	  sqlite.pragma("journal_mode = WAL");
1157	
1158	  try {
1159	    for (const statement of readMigrationStatements()) {
1160	      sqlite.exec(statement);
1161	    }
1162	  } finally {
1163	    sqlite.close();
1164	  }
1165	}
1166	
1167	/** `pnpm db:migrate` runs this file directly; importing it must stay inert. */
1168	if (process.argv[1]?.endsWith("migrate.ts") === true) {
1169	  await runMigrations();
1170	}
1171	
1172	function readMigrationStatements(): readonly string[] {
1173	  const dir = resolve(process.cwd(), MIGRATIONS_DIR);
1174	  if (!existsSync(dir)) return SCHEMA_STATEMENTS;
1175	
1176	  const files = readdirSync(dir)
1177	    .filter((name) => name.endsWith(".sql"))
1178	    .sort();
1179	
1180	  if (files.length === 0) return SCHEMA_STATEMENTS;
1181	
1182	  return files.flatMap((name) =>
1183	    readFileSync(join(dir, name), "utf8")
1184	      .split("--> statement-breakpoint")
1185	      .map((chunk) => chunk.trim())
1186	      .filter(Boolean),
1187	  );
1188	}
